/**
 * Filtered convenience exports
 */
export const ENGLISH_QA = CHATBOT_QA_DATASET.filter((qa) => qa.language === "english");
export const HINGLISH_QA = CHATBOT_QA_DATASET.filter((qa) => qa.language === "hinglish");
export const OFF_TOPIC_QA = CHATBOT_QA_DATASET.filter((qa) => qa.isOffTopic);

/**
 * Normalizes input string for fuzzy keyword comparison
 */
function normalizeText(text) {
  let cleaned = String(text || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // Normalize common phonetic variations in Hinglish queries:
  // "kay" / "kyaa" / "kye" -> "kya"
  // "hey" / "he" / "hy" (when not a greeting at the start) -> "hai"
  cleaned = cleaned
    .replace(/\b(kay|kyaa|kye|kia)\b/g, "kya")
    .replace(/\b(hy|he)\b/g, "hai")
    .replace(/\b(hey)\b/g, (match, offset) => (offset > 0 ? "hai" : "hey"))
    .replace(/\b(intrenship|intrnship|interenship|intership)\b/g, "internship")
    .replace(/\b(intren|intrn)\b/g, "intern");

  return cleaned;
}

const STOP_WORDS = new Set([
  "kya", "kay", "kyaa", "kye", "hai", "hey", "he", "hy", "h", "hota", "hote", "hoti", "hain", "tha", "the", "thi",
  "batao", "bataiye", "bataona", "bataye", "ke", "ka", "ki", "ko", "se", "mein", "me",
  "aur", "ya", "par", "pe", "karo", "karna", "baare", "bare", "kuch", "yeh", "ye", "woh",
  "about", "tell", "me", "what", "is", "are", "the", "a", "an", "do", "does", "in", "of", "to", "for", "and", "or", "how"
]);

/**
 * Matches a user query against the QA dataset.
 * Supports exact question matching, variation matching, and substantive keyword overlap scoring.
 *
 * @param {string} query The user's query
 * @param {"english"|"hinglish"} [langPreference] Optional language filter
 * @returns {object|null} The best matching QA item or null
 */
export function findBestQaMatch(query, langPreference) {
  const normQuery = normalizeText(query);
  if (!normQuery) return null;

  const queryWords = normQuery.split(" ").filter((w) => w.length > 1);
  if (queryWords.length === 0) return null;

  const queryKeywords = queryWords.filter((w) => !STOP_WORDS.has(w));

  let bestMatch = null;
  let highestScore = 0;

  for (const item of CHATBOT_QA_DATASET) {
    if (langPreference && item.language !== langPreference) continue;

    const normQ = normalizeText(item.question);

    // Exact match
    if (normQ === normQuery) {
      return item;
    }

    // Direct variation match
    if (item.variations && item.variations.some((v) => normalizeText(v) === normQuery)) {
      return item;
    }

    const allPhrases = [normQ, ...(item.variations || []).map(normalizeText)];

    for (const phrase of allPhrases) {
      const phraseWords = phrase.split(" ").filter((w) => w.length > 1);
      const phraseKeywords = phraseWords.filter((w) => !STOP_WORDS.has(w));

      // CRITICAL GUARD: Substantive keywords must match!
      // If query has substantive keywords (e.g. "python"), and the phrase does NOT share any
      // substantive keyword (e.g. phrase only has "satellite"), this phrase CANNOT match!
      if (queryKeywords.length > 0) {
        if (phraseKeywords.length === 0) continue;
        const keywordOverlap = queryKeywords.filter((w) => phraseKeywords.includes(w)).length;
        if (keywordOverlap === 0) {
          continue;
        }

        // Substantive keyword overlap score (heavily weighted on real keywords)
        const keywordScore = keywordOverlap / Math.max(queryKeywords.length, phraseKeywords.length);
        
        // Minor boost if all query keywords are present.
        // Never grant containment bonus for single-word queries against multi-word phrases,
        // preventing a 1-word query (e.g. "program") from inappropriately matching unrelated multi-word topics (e.g. "internship program").
        const isTrueContainment = queryKeywords.length > 1
          ? queryKeywords.every((kw) => phraseKeywords.includes(kw))
          : (phraseKeywords.length === 1 && queryKeywords[0] === phraseKeywords[0]);
        const containmentBonus = isTrueContainment ? 0.25 : 0;
        
        const finalScore = keywordScore + containmentBonus;
        if (finalScore > highestScore) {
          highestScore = finalScore;
          bestMatch = item;
        }
      } else {
        // Fallback for query containing only stop words
        let matchedCount = 0;
        for (const qw of queryWords) {
          if (phraseWords.includes(qw)) matchedCount++;
        }
        const currentScore = matchedCount / Math.max(queryWords.length, phraseWords.length);
        if (currentScore > highestScore) {
          highestScore = currentScore;
          bestMatch = item;
        }
      }
    }
  }

  // Threshold: only return if substantive match confidence is sufficient
  if (highestScore >= 0.55) {
    return bestMatch;
  }

  return null;
}
